54	/**
55	 * A zookeeper based lock. This {@link LockProvider} implementation allows to lock table operations
56	 * using zookeeper. Users need to have a Zookeeper cluster deployed to be able to use this lock.
57	 */
58	@NotThreadSafe
59	public class ZookeeperBasedLockProvider implements LockProvider<InterProcessMutex>, Serializable {
60	
61	  private static final Logger LOG = LoggerFactory.getLogger(ZookeeperBasedLockProvider.class);
62	
63	  private final transient CuratorFramework curatorFrameworkClient;
64	  private volatile InterProcessMutex lock = null;
65	  protected LockConfiguration lockConfiguration;
66	
67	  public ZookeeperBasedLockProvider(final LockConfiguration lockConfiguration, final StorageConfiguration<?> conf) {
68	    checkRequiredProps(lockConfiguration);
69	    this.lockConfiguration = lockConfiguration;
70	    this.curatorFrameworkClient = CuratorFrameworkFactory.builder()
71	        .connectString(lockConfiguration.getConfig().getString(ZK_CONNECT_URL_PROP_KEY))
72	        .retryPolicy(new BoundedExponentialBackoffRetry(lockConfiguration.getConfig().getInteger(LOCK_ACQUIRE_RETRY_WAIT_TIME_IN_MILLIS_PROP_KEY),
73	            lockConfiguration.getConfig().getInteger(LOCK_ACQUIRE_RETRY_MAX_WAIT_TIME_IN_MILLIS_PROP_KEY), lockConfiguration.getConfig().getInteger(LOCK_ACQUIRE_NUM_RETRIES_PROP_KEY)))
74	        .sessionTimeoutMs(lockConfiguration.getConfig().getInteger(ZK_SESSION_TIMEOUT_MS_PROP_KEY, DEFAULT_ZK_SESSION_TIMEOUT_MS))
75	        .connectionTimeoutMs(lockConfiguration.getConfig().getInteger(ZK_CONNECTION_TIMEOUT_MS_PROP_KEY, DEFAULT_ZK_CONNECTION_TIMEOUT_MS))
76	        .build();
77	    this.curatorFrameworkClient.start();
78	    createPathIfNotExists();
79	  }
80	
81	  private String getLockPath() {
82	    return lockConfiguration.getConfig().getString(ZK_BASE_PATH_PROP_KEY) + "/"
83	        + this.lockConfiguration.getConfig().getString(ZK_LOCK_KEY_PROP_KEY);
84	  }
85	
86	  private void createPathIfNotExists() {
87	    try {
88	      String lockPath = getLockPath();
89	      LOG.info(String.format("Creating zookeeper path %s if not exists", lockPath));
90	      String[] parts = lockPath.split("/");
91	      StringBuilder currentPath = new StringBuilder();
92	      for (String part : parts) {
93	        if (!part.isEmpty()) {
94	          currentPath.append("/").append(part);
95	          createNodeIfNotExists(currentPath.toString());
96	        }
97	      }
98	    } catch (Exception e) {
99	      LOG.error("Failed to create ZooKeeper path: " + e.getMessage());
100	      throw new HoodieLockException("Failed to initialize ZooKeeper path", e);
101	    }
102	  }
103	
104	  private void createNodeIfNotExists(String path) throws Exception {
105	    if (this.curatorFrameworkClient.checkExists().forPath(path) == null) {
106	      try {
107	        this.curatorFrameworkClient.create().forPath(path);
108	        // to avoid failure due to synchronous calls.
109	      } catch (KeeperException e) {
110	        if (e.code() == KeeperException.Code.NODEEXISTS) {
111	          LOG.debug(String.format("Node already exist for path = %s", path));
112	        } else {
113	          throw new HoodieLockException("Failed to create zookeeper node", e);
114	        }
115	      }
116	    }
117	  }
