122	    checkRequiredProps(lockConfiguration);
123	    this.lockConfiguration = lockConfiguration;
124	    this.curatorFrameworkClient = curatorFrameworkClient;
125	    synchronized (this.curatorFrameworkClient) {
126	      if (this.curatorFrameworkClient.getState() != CuratorFrameworkState.STARTED) {
127	        this.curatorFrameworkClient.start();
128	        createPathIfNotExists();
129	      }
130	    }
131	  }
