110	  @Override
111	  public boolean tryLock(long time, TimeUnit unit) {
112	    LOG.info(generateLogStatement(LockState.ACQUIRING, generateLogSuffixString()));
113	    try {
114	      lock = client.acquireLock(AcquireLockOptions.builder(dynamoDBPartitionKey)
115	          .withAdditionalTimeToWaitForLock(time)
116	          .withTimeUnit(TimeUnit.MILLISECONDS)
117	          .build());
118	      LOG.info(generateLogStatement(LockState.ACQUIRED, generateLogSuffixString()));
119	    } catch (InterruptedException e) {
120	      throw new HoodieLockException(generateLogStatement(LockState.FAILED_TO_ACQUIRE, generateLogSuffixString()), e);
121	    } catch (LockNotGrantedException e) {
122	      return false;
123	    }
124	    return lock != null && !lock.isExpired();
125	  }
