128	  public void unlock() {
129	    try {
130	      LOG.info(generateLogStatement(LockState.RELEASING, generateLogSuffixString()));
131	      if (lock == null) {
132	        return;
133	      }
134	      if (!client.releaseLock(lock)) {
135	        LOG.warn("The lock has already been stolen");
136	      }
137	      lock = null;
138	      LOG.info(generateLogStatement(LockState.RELEASED, generateLogSuffixString()));
139	    } catch (Exception e) {
140	      throw new HoodieLockException(generateLogStatement(LockState.FAILED_TO_RELEASE, generateLogSuffixString()), e);
141	    }
142	  }
